const nomes = {{productArrayNames}}; // Ex: ["Bolo de Cenoura", "Bolo de Fubá"]
const descricoes = {{productArrayDescription}}; // Ex: ["Delicioso...", "Feito com carinho..."]

const listaFormatada = nomes
  .map((nome, i) => `✨ *${i + 1}*: ${nome}\n📝 _${descricoes[i]}_`)
  .join("\n\n");

setVariable("listaFormatada", listaFormatada);
setVariable("nomesProdutos", nomes);

const nomes = {{nomesProdutos}};
const ids = {{productArrayId}};
const input = parseInt({{escolhaProduto}});
const index = input - 1;

if (isNaN(input) || index < 0 || index >= nomes.length) {
  setVariable("produtoEscolhido", null);
  setVariable("produtoIdEscolhido", null);
} else {
  setVariable("produtoEscolhido", nomes[index]);
  setVariable("produtoIdEscolhido", ids[index]);
}

// value received from Typebot variable
const price = {{price}};

// Function to parse price formats like: R$25,90 / 25,9 / 25.900,50 / 25
function parseToDecimal(value) {
  if (!value) return null;

  return Number(
    value
      .toString()
      .replace(/[R$\s]/gi, "") // remove R$, $
      .replace(/\./g, "")      // remove thousand separators
      .replace(",", ".")       // convert decimal comma to dot
  );
}

// Parse and store in Typebot variable
const parsedPrice = parseToDecimal(price);

setVariable("parsedPrice", parsedPrice);
